import { z } from 'zod';

/** UUIDv7 identifiers are generated by the application (time-sortable, offline-safe). */
export const Id = z.uuid();
export type Id = z.infer<typeof Id>;

/** ISO-8601 UTC timestamp string, e.g. "2026-10-02T15:00:00.000Z". */
export const Timestamp = z.iso.datetime({ offset: true });
export type Timestamp = z.infer<typeof Timestamp>;

/** IANA time zone name, e.g. "Asia/Kolkata". */
export const TimeZone = z.string().refine(
  (tz) => {
    try {
      new Intl.DateTimeFormat('en-US', { timeZone: tz });
      return true;
    } catch {
      return false;
    }
  },
  { message: 'Invalid IANA time zone' },
);

/** Stable machine-readable problem codes used by clients for logic. */
export const ProblemCode = z.enum([
  'VALIDATION_FAILED',
  'UNAUTHENTICATED',
  'FORBIDDEN',
  'NOT_FOUND',
  'CONFLICT',
  'RATE_LIMITED',
  'PAYLOAD_TOO_LARGE',
  'SERVICE_UNAVAILABLE',
  'INTERNAL',
  'SESSION_OVERLAP',
  'SESSION_STATE_INVALID',
  'VERSION_CONFLICT',
  'EMAIL_TAKEN',
  'INVALID_CREDENTIALS',
  'EMAIL_NOT_VERIFIED',
  'TOKEN_INVALID',
  'PAIRING_CODE_INVALID',
  'DOMAIN_LIST_CONFLICT',
  'AI_UNAVAILABLE',
  'QUOTA_EXCEEDED',
]);
export type ProblemCode = z.infer<typeof ProblemCode>;

export const FieldError = z.object({
  path: z.string(),
  message: z.string(),
});

/** RFC 9457 problem details, extended with `code` and `requestId`. */
export const Problem = z.object({
  type: z.string(),
  title: z.string(),
  status: z.number().int(),
  code: ProblemCode,
  detail: z.string().optional(),
  requestId: z.string().optional(),
  errors: z.array(FieldError).optional(),
});
export type Problem = z.infer<typeof Problem>;

/** Cursor pagination query and response envelope. */
export const PageQuery = z.object({
  cursor: z.string().optional(),
  limit: z.coerce.number().int().min(1).max(100).default(20),
});
export type PageQuery = z.infer<typeof PageQuery>;

export const page = <T extends z.ZodType>(item: T) =>
  z.object({
    items: z.array(item),
    nextCursor: z.string().nullable(),
  });

export const HealthResponse = z.object({
  status: z.literal('ok'),
  service: z.string(),
  version: z.string(),
  time: Timestamp,
});

export const ReadyResponse = z.object({
  status: z.enum(['ready', 'not_ready']),
  checks: z.record(z.string(), z.enum(['ok', 'fail'])),
});
